<?php require_once __DIR__.'/auth.php'; $title='Tour Types'; include 'admin-head.php'; include 'sidebar.php'; include 'topbar.php'; ?><main class="main"><?php $items=read_data('tourtypes');if($_SERVER['REQUEST_METHOD']==='POST'){if(($_POST['action']??'')==='delete'){$id=(int)$_POST['id'];$items=array_values(array_filter($items,fn($x)=>(int)$x['id']!==$id));}else{$id=(int)($_POST['id']??0);$r=['id'=>$id?:next_id($items),'name'=>trim($_POST['name']??''),'description'=>trim($_POST['description']??'')];if($id){foreach($items as &$x)if((int)$x['id']===$id)$x=$r;unset($x);}else$items[]=$r;}write_data('tourtypes',$items);redirect('tourtype.php');}$edit=null;if(isset($_GET['edit']))foreach($items as $x)if((int)$x['id']===(int)$_GET['edit'])$edit=$x;?>
<div class="row g-4"><div class="col-lg-4"><div class="card shadow-sm p-4"><h5 class="fw-bold">Tour Type</h5><form method="post"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><input name="name" class="form-control mb-3" placeholder="Type name" value="<?=e($edit['name']??'')?>" required><textarea name="description" class="form-control mb-3" placeholder="Description"><?=e($edit['description']??'')?></textarea><button class="btn btn-success w-100">Save</button></form></div></div><div class="col-lg-8"><div class="card shadow-sm"><div class="table-responsive"><table class="table"><thead><tr><th>Name</th><th>Description</th><th></th></tr></thead><tbody><?php foreach($items as $x): ?><tr><td><?=e($x['name'])?></td><td><?=e($x['description'])?></td><td class="text-end"><a href="?edit=<?=$x['id']?>" class="btn btn-sm btn-outline-primary">Edit</a><form class="d-inline" method="post"><input type="hidden" name="id" value="<?=$x['id']?>"><input type="hidden" name="action" value="delete"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></div><?php include 'admin-foot.php'; ?>